/bin/bash -lc "node --input-type=module <<'EOF'
for (const route of ['/', '/about']) {
  const response = await fetch("'`http://127.0.0.1:3000${route}`)
  const html = await response.text()
  console.log(`${route}: ${response.status}`)
  console.log(`  title: ${html.match(/<title>(.*?)<'"\\/title>/)?.[1] ?? 'missing'}"'`)
  console.log(`  expected content: ${html.includes(route === '"'/' ? 'Welcome to our Next.js application"'!'"' : 'This is the about page of our Next.js application.')}"'`)
}
EOF'

